# Design Note

**Data structures:** A character-by-character state machine with explicit states (BETWEEN, IN_STR, IN_NUM, IN_LIT, IN_CONT, NUM_TERM, LIT_TERM). A stack of `(is_obj, frame_state)` tuples tracks nested containers. The buffer for the current top-level value is a `list[str]` appended char-by-char; `"".join()` is called only once when a value is emitted.

**Complexity:** Each character is inspected exactly once in O(1) within the state machine → O(n) total, independent of chunk boundaries.

**Concurrency:** Single-threaded per connection; no locks needed.

### solution.py

```python
"""Incremental JSON stream decoder for log ingestion (Python 3.12, stdlib only)."""

from __future__ import annotations

import json
from typing import Any


class JSONStreamError(ValueError):
    """Base class for stream-level JSON parse errors."""

    def __init__(self, msg: str = "", offset: int = 0) -> None:
        super().__init__(msg)
        self.offset = offset


class IncompleteJSONError(JSONStreamError):
    """Raised when close() is called with an unfinished value."""


class BufferLimitError(JSONStreamError):
    """Raised when a single value exceeds max_buffer characters."""


# ---------------------------------------------------------------------------
# Internal enums (kept as ints for speed)
# ---------------------------------------------------------------------------

# Number sub-states
_NUM_START = 0
_NUM_AFTER_MINUS = 1
_NUM_IN_INT = 2       # started with 1-9
_NUM_ZERO = 3         # int part is exactly "0"
_NUM_IN_FRAC = 4
_NUM_EXP_START = 5    # after e/E, expecting +/-/digit
_NUM_EXP_SIGN = 6     # after sign, expecting digit
_NUM_EXP_DIGITS = 7

# Container frame states (int constants)
_OBJ_EXPECT_KEY = 0
_OBJ_AFTER_KEY = 1
_OBJ_AFTER_COLON = 2
_OBJ_AFTER_VALUE = 3
_OBJ_AFTER_COMMA = 4
_ARR_EXPECT_VALUE = 5
_ARR_AFTER_VALUE = 6
_ARR_AFTER_COMMA = 7

# Literal identifiers
_LIT_TRUE = 0
_LIT_FALSE = 1
_LIT_NULL = 2
_LIT_STRINGS = ("true", "false", "null")

# Whitespace per RFC 8259
_WS = frozenset(" \t\n\r")


class JSONStreamDecoder:
    """Feed raw text chunks; get back decoded top-level JSON values."""

    def __init__(self, *, max_buffer: int = 10_000_000) -> None:
        if not isinstance(max_buffer, int) or max_buffer < 1:
            raise ValueError("max_buffer must be an int >= 1")
        self._max_buffer = max_buffer
        self._offset: int = 0
        self._closed = False
        self._errored = False

        # --- Top-level phase ---
        # BETWEEN | IN_STR | IN_STR_ESC | IN_STR_HEX | IN_NUM | IN_LIT | IN_CONT | NUM_TERM | LIT_TERM
        self._phase = "BETWEEN"

        # --- Buffer for the current top-level value ---
        self._buf: list[str] = []
        self._buf_start: int = 0  # absolute offset of first char of current value

        # --- Top-level string scanner ---
        self._hex_count = 0

        # --- Top-level number scanner ---
        self._num_state = _NUM_START

        # --- Top-level literal scanner ---
        self._lit_type = 0
        self._lit_pos = 0

        # --- Container stack: list of (is_obj: bool, frame_state: int) ---
        self._cont: list[tuple[bool, int]] = []
        self._depth = 0

        # --- Container value scanner (active when depth > 0 and scanning a value) ---
        # Reuses _num_state, _lit_type, _lit_pos, _hex_count when in container.
        self._c_in_str = False
        self._c_str_esc = False  # True = just saw backslash
        self._c_str_hex = 0      # >0 counting hex digits after \u
        self._c_in_num = False
        self._c_in_lit = False

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------

    def feed(self, chunk: str) -> list[Any]:
        if self._errored:
            raise JSONStreamError("stream in error state", self._offset)
        if self._closed:
            raise JSONStreamError("stream already closed", self._offset)
        if not isinstance(chunk, str):
            raise TypeError("chunk must be a str")
        results: list[Any] = []
        for ch in chunk:
            self._step(ch, results)
        return results

    def close(self) -> list[Any]:
        if self._errored:
            raise JSONStreamError("stream in error state", self._offset)
        if self._closed:
            raise JSONStreamError("stream already closed", self._offset)
        self._closed = True
        results: list[Any] = []
        if self._phase == "BETWEEN":
            return results
        if self._phase == "NUM_TERM":
            results.append(self._decode_text())
            return results
        if self._phase == "LIT_TERM":
            results.append(self._decode_text())
            return results
        # Anything else is an incomplete value
        raise IncompleteJSONError("incomplete JSON stream", self._offset)

    def pending(self) -> int:
        if self._phase == "BETWEEN":
            return 0
        return len(self._buf)

    # ------------------------------------------------------------------
    # Core character dispatch
    # ------------------------------------------------------------------

    def _step(self, ch: str, results: list[Any]) -> None:
        off = self._offset
        self._offset += 1
        phase = self._phase

        if phase == "BETWEEN":
            self._do_between(ch, off)
        elif phase == "IN_STR":
            self._do_str(ch, off)
        elif phase == "IN_STR_ESC":
            self._do_str_esc(ch, off)
        elif phase == "IN_STR_HEX":
            self._do_str_hex(ch, off)
        elif phase == "IN_NUM":
            self._do_num_top(ch, off)
        elif phase == "IN_LIT":
            self._do_lit_top(ch, off)
        elif phase == "IN_CONT":
            self._do_cont(ch, off, results)
        elif phase == "NUM_TERM":
            self._do_num_term(ch, off, results)
        elif phase == "LIT_TERM":
            self._do_lit_term(ch, off, results)

    # ------------------------------------------------------------------
    # BETWEEN: skipping whitespace between top-level values
    # ------------------------------------------------------------------

    def _do_between(self, ch: str, off: int) -> None:
        if ch in _WS:
            return
        # Start of a value
        self._buf_start = off
        self._buf = [ch]
        if self._check_buf_limit(off):
            return
        if ch == '"':
            self._phase = "IN_STR"
        elif ch == '{':
            self._cont.append((True, _OBJ_EXPECT_KEY))
            self._depth = 1
            self._phase = "IN_CONT"
        elif ch == '[':
            self._cont.append((False, _ARR_EXPECT_VALUE))
            self._depth = 1
            self._phase = "IN_CONT"
        elif ch == '-':
            self._num_state = _NUM_AFTER_MINUS
            self._phase = "IN_NUM"
        elif '0' <= ch <= '9':
            self._num_state = _NUM_ZERO if ch == '0' else _NUM_IN_INT
            self._phase = "IN_NUM"
        elif ch == 't':
            self._lit_type = _LIT_TRUE
            self._lit_pos = 1
            self._phase = "IN_LIT"
        elif ch == 'f':
            self._lit_type = _LIT_FALSE
            self._lit_pos = 1
            self._phase = "IN_LIT"
        elif ch == 'n':
            self._lit_type = _LIT_NULL
            self._lit_pos = 1
            self._phase = "IN_LIT"
        else:
            self._fail(off, f"unexpected character {ch!r}")

    # ------------------------------------------------------------------
    # Top-level string scanning
    # ------------------------------------------------------------------

    def _do_str(self, ch: str, off: int) -> None:
        self._buf.append(ch)
        if self._check_buf_limit(off):
            return
        if ch == '"':
            self._phase = "BETWEEN"
            results = self._pop_results()
            # results list is used in caller; here just signal completion
            # We need to emit. Store in a pending list.
            self._pending_results = self._pending_results  # will be handled in _step
            # Actually let's handle emission via _emit()
            self._emit()
        elif ch == '\\':
            self._phase = "IN_STR_ESC"
        elif ch <= '\x1f':  # U+0000 .. U+001F
            self._fail(off, "unescaped control character in string")

    # ------------------------------------------------------------------
    # String escape sequences
    # ------------------------------------------------------------------

    def _do_str_esc(self, ch: str, off: int) -> None:
        self._buf.append(ch)
        if self._check_buf_limit(off):
            return
        if ch in '"\\/bfnrt':
            self._phase = "IN_STR"
        elif ch == 'u':
            self._hex_count = 1
            self._phase = "IN_STR_HEX"
        else:
            self._fail(off, f"invalid escape \\{ch!r}")

    def _do_str_hex(self, ch: str, off: int) -> None:
        self._buf.append(ch)
        if self._check_buf_limit(off):
            return
        if ch in '0123456789abcdefABCDEF':
            self._hex_count += 1
            if self._hex_count > 4:
                self._phase = "IN_STR"
        else:
            self._fail(off, "invalid \\u escape")

    # ------------------------------------------------------------------
    # Top-level number scanning
    # ------------------------------------------------------------------

    def _do_num_top(self, ch: str, off: int) -> None:
        self._buf.append(ch)
        if self._check_buf_limit(off):
            return
        ns = self._num_state
        if ns == _NUM_AFTER_MINUS:
            if '0' <= ch <= '9':
                self._num_state = _NUM_ZERO if ch == '0' else _NUM_IN_INT
            else:
                self._fail(off, "expected digit after '-'")
        elif ns == _NUM_IN_INT:
            if '0' <= ch <= '9':
                pass  # stay in NUM_IN_INT
            elif ch == '.':
                self._num_state = _NUM_IN_FRAC
            elif ch in 'eE':
                self._num_state = _NUM_EXP_START
            else:
                # terminator char – number is complete
                self._phase = "NUM_TERM"
                # re-process this char as terminator
                self._num_term_char(ch, off)
                return
        elif ns == _NUM_ZERO:
            if '0' <= ch <= '9':
                self._fail(off, "leading zero")
            elif ch == '.':
                self._num_state = _NUM_IN_FRAC
            elif ch in 'eE':
                self._num_state = _NUM_EXP_START
            else:
                self._phase = "NUM_TERM"
                self._num_term_char(ch, off)
                return
        elif ns == _NUM_IN_FRAC:
            if '0' <= ch <= '9':
                pass
            elif ch in 'eE':
                self._num_state = _NUM_EXP_START
            else:
                self._fail(off, "expected digit in fraction")
        elif ns == _NUM_EXP_START:
            if ch in '+-':
                self._num_state = _NUM_EXP_SIGN
            elif '0' <= ch <= '9':
                self._num_state = _NUM_EXP_DIGITS
            else:
                self._fail(off, "expected digit or sign in exponent")
        elif ns == _NUM_EXP_SIGN:
            if '0' <= ch <= '9':
                self._num_state = _NUM_EXP_DIGITS
            else:
                self._fail(off, "expected digit in exponent")
        elif ns == _NUM_EXP_DIGITS:
            if '0' <= ch <= '9':
                pass
            else:
                self._fail(off, "invalid character in number")

    def _num_term_char(self, ch: str, off: int) -> None:
        """Called when a top-level number is syntactically complete and we see the terminator."""
        if ch in _WS:
            # number terminates; next char will be processed in BETWEEN
            # Remove the terminator from buffer (it's not part of the value)
            self._buf.pop()
            # The number is complete – emit it
            self._phase = "NUM_TERM"
        elif ch in '{[''"':
            self._buf.pop()
            self._phase = "NUM_TERM"
            # The char starts the next value; we need to process it in BETWEEN.
            # Defer: next char processing will handle it.
            # Store this char for next step.
            self._deferred = ch
            self._deferred_off = off
        else:
            self._buf.pop()
            self._fail(off, f"invalid character after number: {ch!r}")

    # ------------------------------------------------------------------
    # Top-level literal scanning
    # ------------------------------------------------------------------

    def _do_lit_top(self, ch: str, off: int) -> None:
        self._buf.append(ch)
        if self._check_buf_limit(off):
            return
        target = _LIT_STRINGS[self._lit_type]
        if ch == target[self._lit_pos]:
            self._lit_pos += 1
            if self._lit_pos == len(target):
                self._phase = "LIT_TERM"
        else:
            self._fail(off, f"invalid literal")

    # ------------------------------------------------------------------
    # NUM_TERM / LIT_TERM: waiting for terminator after a complete value
    # ------------------------------------------------------------------

    def _do_num_term(self, ch: str, off: int, results: list[Any]) -> None:
        if ch in _WS:
            results.append(self._decode_text())
            self._buf = []
            self._phase = "BETWEEN"
        elif ch in '{[''"':
            results.append(self._decode_text())
            self._buf = []
            self._phase = "BETWEEN"
            self._deferred = ch
            self._deferred_off = off
        else:
            self._fail(off, f"invalid character after number: {ch!r}")

    def _do_lit_term(self, ch: str, off: int, results: list[Any]) -> None:
        if ch in _WS:
            results.append(self._decode_text())
            self._buf = []
            self._phase = "BETWEEN"
        elif ch in '{[''"':
            results.append(self._decode_text())
            self._buf = []
            self._phase = "BETWEEN"
            self._deferred = ch
            self._deferred_off = off
        else:
            self._fail(off, f"invalid character after literal: {ch!r}")

    # ------------------------------------------------------------------
    # Container scanning (IN_CONT phase)
    # ------------------------------------------------------------------

    def _do_cont(self, ch: str, off: int, results: list[Any]) -> None:
        self._buf.append(ch)
        if self._check_buf_limit(off):
            return

        # If we're scanning a string inside the container
        if self._c_in_str:
            self._cont_str_char(ch, off)
            return
        # Scanning a number inside the container
        if self._c_in_num:
            self._cont_num_char(ch, off)
            return
        # Scanning a literal inside the container
        if self._c_in_lit:
            self._cont_lit_char(ch, off)
            return

        # Structural / start-of-value processing
        is_obj, fstate = self._cont[-1]

        if is_obj:
            self._cont_obj_struct(ch, off, fstate, results)
        else:
            self._cont_arr_struct(ch, off, fstate, results)

    # --- Container string ---
    def _cont_str_char(self, ch: str, off: int) -> None:
        if self._c_str_esc:
            self._c_str_esc = False
            if ch in '"\\/bfnrt':
                pass  # valid escape, continue in string
            elif ch == 'u':
                self._c_str_hex = 1
            else:
                self._fail(off, f"invalid escape \\{ch!r}")
            return
        if self._c_str_hex > 0:
            if ch in '0123456789abcdefABCDEF':
                self._c_str_hex += 1
                if self._c_str_hex > 4:
                    self._c_str_hex = 0
            else:
                self._fail(off, "invalid \\u escape")
            return
        # Normal string char
        if ch == '"':
            self._c_in_str = False
            # String complete – transition parent
            self._cont_value_complete()
        elif ch == '\\':
            self._c_str_esc = True
        elif ch <= '\x1f':
            self._fail(off, "unescaped control character in string")

    # --- Container number ---
    def _cont_num_char(self, ch: str, off: int) -> None:
        ns = self._num_state
        if ns == _NUM_AFTER_MINUS:
            if '0' <= ch <= '9':
                self._num_state = _NUM_ZERO if ch == '0' else _NUM_IN_INT
            else:
                self._fail(off, "expected digit after '-'")
        elif ns == _NUM_IN_INT:
            if '0' <= ch <= '9':
                pass
            elif ch == '.':
                self._num_state = _NUM_IN_FRAC
            elif ch in 'eE':
                self._num_state = _NUM_EXP_START
            elif ch in ',}]':
                self._c_in_num = False
                self._cont_value_complete()
                # Process the structural char
                self._cont_after_value(ch, off)
            else:
                self._fail(off, f"invalid character in number: {ch!r}")
        elif ns == _NUM_ZERO:
            if '0' <= ch <= '9':
                self._fail(off, "leading zero")
            elif ch == '.':
                self._num_state = _NUM_IN_FRAC
            elif ch in 'eE':
                self._num_state = _NUM_EXP_START
            elif ch in ',}]':
                self._c_in_num = False
                self._cont_value_complete()
                self._cont_after_value(ch, off)
            else:
                self._fail(off, f"invalid character in number: {ch!r}")
        elif ns == _NUM_IN_FRAC:
            if '0' <= ch <= '9':
                pass
            elif ch in 'eE':
                self._num_state = _NUM_EXP_START
            elif ch in ',}]':
                self._c_in_num = False
                self._cont_value_complete()
                self._cont_after_value(ch, off)
            else:
                self._fail(off, "expected digit in fraction")
        elif ns == _NUM_EXP_START:
            if ch in '+-':
                self._num_state = _NUM_EXP_SIGN
            elif '0' <= ch <= '9':
                self._num_state = _NUM_EXP_DIGITS
            elif ch in ',}]':
                self._fail(off, "incomplete exponent")
            else:
                self._fail(off, "expected digit or sign in exponent")
        elif ns == _NUM_EXP_SIGN:
            if '0' <= ch <= '9':
                self._num_state = _NUM_EXP_DIGITS
            elif ch in ',}]':
                self._fail(off, "incomplete exponent")
            else:
                self._fail(off, "expected digit in exponent")
        elif ns == _NUM_EXP_DIGITS:
            if '0' <= ch <= '9':
                pass
            elif ch in ',}]':
                self._c_in_num = False
                self._cont_value_complete()
                self._cont_after_value(ch, off)
            else:
                self._fail(off, f"invalid character in number: {ch!r}")

    # --- Container literal ---
    def _cont_lit_char(self, ch: str, off: int) -> None:
        target = _LIT_STRINGS[self._lit_type]
        if ch == target[self._lit_pos]:
            self._lit_pos += 1
            if self._lit_pos == len(target):
                self._c_in_lit = False
                self._cont_value_complete()
        elif ch in ',}]':
            self._fail(off, "invalid literal")
        else:
            self._fail(off, "invalid literal")

    # --- Container structural: object ---
    def _cont_obj_struct(self, ch: str, off: int, fstate: int, results: list[Any]) -> None:
        if fstate == _OBJ_EXPECT_KEY:
            if ch == '"':
                self._c_in_str = True
                self._cont[-1] = (True, fstate)  # stay; string tracks key
                return
            if ch == '}':
                # Only valid if this is the FIRST token (empty object)
                # Check: buffer should be just '{' so far (with possible whitespace)
                # Actually, frame state EXPECT_KEY is only set at start; after a comma
                # in obj we go to AFTER_COMMA which also expects key.
                # Empty object: '{' then '}' → valid.
                self._cont_pop(off, results)
                return
            if ch in _WS:
                return
            self._fail(off, f"expected string key, got {ch!r}")
        elif fstate == _OBJ_AFTER_KEY:
            if ch == ':':
                self._cont[-1] = (True, _OBJ_AFTER_COLON)
            elif ch in _WS:
                pass
            else:
                self._fail(off, f"expected ':', got {ch!r}")
        elif fstate == _OBJ_AFTER_COLON:
            self._cont_start_value(ch, off)
        elif fstate == _OBJ_AFTER_VALUE:
            if ch == ',':
                self._cont[-1] = (True, _OBJ_AFTER_COMMA)
            elif ch == '}':
                self._cont_pop(off, results)
            elif ch in _WS:
                pass
            else:
                self._fail(off, f"expected ',' or '}}', got {ch!r}")
        elif fstate == _OBJ_AFTER_COMMA:
            if ch == '"':
                self._c_in_str = True
                self._cont[-1] = (True, fstate)
                return
            if ch in _WS:
                return
            self._fail(off, f"expected string key, got {ch!r}")

    # --- Container structural: array ---
    def _cont_arr_struct(self, ch: str, off: int, fstate: int, results: list[Any]) -> None:
        if fstate == _ARR_EXPECT_VALUE:
            if ch == ']':
                # Empty array only valid at the very start
                self._cont_pop(off, results)
            elif ch in _WS:
                return
            else:
                self._cont_start_value(ch, off)
        elif fstate == _ARR_AFTER_VALUE:
            if ch == ',':
                self._cont[-1] = (False, _ARR_AFTER_COMMA)
            elif ch == ']':
                self._cont_pop(off, results)
            elif ch in _WS:
                pass
            else:
                self._fail(off, f"expected ',' or ']', got {ch!r}")
        elif fstate == _ARR_AFTER_COMMA:
            if ch in _WS:
                return
            else:
                self._cont_start_value(ch, off)

    # --- Start a value inside a container ---
    def _cont_start_value(self, ch: str, off: int) -> None:
        if ch == '"':
            self._c_in_str = True
        elif ch == '{':
            self._cont.append((True, _OBJ_EXPECT_KEY))
            self._depth += 1
        elif ch == '[':
            self._cont.append((False, _ARR_EXPECT_VALUE))
            self._depth += 1
        elif ch == '-':
            self._c_in_num = True
            self._num_state = _NUM_AFTER_MINUS
        elif '0' <= ch <= '9':
            self._c_in_num = True
            self._num_state = _NUM_ZERO if ch == '0' else _NUM_IN_INT
        elif ch == 't':
            self._c_in_lit = True
            self._lit_type = _LIT_TRUE
            self._lit_pos = 1
        elif ch == 'f':
            self._c_in_lit = True
            self._lit_type = _LIT_FALSE
            self._lit_pos = 1
        elif ch == 'n':
            self._c_in_lit = True
            self._lit_type = _LIT_NULL
            self._lit_pos = 1
        else:
            self._fail(off, f"unexpected character in container: {ch!r}")

    # --- A value completed inside the container: transition parent frame ---
    def _cont_value_complete(self) -> None:
        is_obj, fstate = self._cont[-1]
        if is_obj:
            if fstate == _OBJ_EXPECT_KEY:
                self._cont[-1] = (True, _OBJ_AFTER_KEY)
            elif fstate == _OBJ_AFTER_COLON:
                self._cont[-1] = (True, _OBJ_AFTER_VALUE)
            # AFTER_COMMA → key string completed → AFTER_KEY handled in obj_struct
            elif fstate == _OBJ_AFTER_COMMA:
                self._cont[-1] = (True, _OBJ_AFTER_KEY)
        else:
            self._cont[-1] = (False, _ARR_AFTER_VALUE)

    # --- After a value completes, process the structural char that terminated it ---
    def _cont_after_value(self, ch: str, off: int) -> None:
        """Called after a number/literal in a container is terminated by , } or ]."""
        # The value is complete; parent already in AFTER_VALUE.
        # Now handle the structural char.
        is_obj, fstate = self._cont[-1]
        if ch == ',':
            self._cont[-1] = (True, _OBJ_AFTER_COMMA) if is_obj else (False, _ARR_AFTER_COMMA)
        elif ch == '}':
            if not is_obj:
                self._fail(off, "mismatched closing bracket")
            self._depth -= 1
            self._cont.pop()
            if self._depth == 0:
                # Top-level container complete
                self._phase = "BETWEEN"
                self._emit_cont()
            else:
                self._cont_value_complete()
        elif ch == ']':
            if is_obj:
                self._fail(off, "mismatched closing bracket")
            self._depth -= 1
            self._cont.pop()
            if self._depth == 0:
                self._phase = "BETWEEN"
                self._emit_cont()
            else:
                self._cont_value_complete()

    # --- Pop a container (closing bracket) ---
    def _cont_pop(self, off: int, results: list[Any]) -> None:
        self._depth -= 1
        self._cont.pop()
        if self._depth == 0:
            self._phase = "BETWEEN"
            self._emit_cont()
        else:
            self._cont_value_complete()

    # ------------------------------------------------------------------
    # Emission helpers
    # ------------------------------------------------------------------

    def _emit(self) -> None:
        """Emit the completed top-level value from the buffer (for strings/containers)."""
        # We store the value; the caller (feed loop) collects via _pending_results
        # Instead, use a simple approach: store in a list that _step picks up.
        # Actually, let's just use a simple mechanism: _emit pushes to self._emit_queue.
        self._emit_queue.append(self._decode_text())
        self._buf = []

    def _emit_cont(self) -> None:
        self._emit_queue.append(self._decode_text())
        self._buf = []

    def _decode_text(self) -> Any:
        return json.loads("".join(self._buf))

    # ------------------------------------------------------------------
    # Buffer limit check
    # ------------------------------------------------------------------

    def _check_buf_limit(self, off: int) -> bool:
        """Return True if limit was exceeded (caller should stop processing this char)."""
        if len(self._buf) > self._max_buffer:
