        if ph == "BETWEEN":
            self._do_between(ch, off)
        elif ph == "STR":
            self._do_str(ch, off)
        elif ph == "STR_ESC":
            self._do_str_esc(ch, off)
        elif ph == "STR_HEX":
            self._do_str_hex(ch, off)
        elif ph == "NUM":
            self._do_num(ch, off, out)
        elif ph == "LIT":
            self._do_lit(ch, off)
        elif ph == "CONT":
            self._do_cont(ch, off, out)
        elif ph == "NUMTERM":
            self._do_numterm(ch, off, out)
        elif ph == "LITERM":
            self._do_literm(ch, off, out)

    # --- BETWEEN ---
    def _do_between(self, ch: str, off: int) -> None:
        if ch in _WS:
            return
        self._buf = [ch]
        if self._check_limit(off):
            return
        if ch == '"':
            self._ph = "STR"
        elif ch == '{':
            self._stk.append((True, _OB_KEY)); self._depth = 1; self._ph = "CONT"
        elif ch == '[':
            self._stk.append((False, _AR_VAL)); self._depth = 1; self._ph = "CONT"
        elif ch == '-':
            self._ns = _NS_AFTER_MINUS; self._ph = "NUM"
        elif '0' <= ch <= '9':
            self._ns = _NS_ZERO if ch == '0' else _NS_INT; self._ph = "NUM"
        elif ch == 't':
            self._lt = 0; self._lp = 1; self._ph = "LIT"
        elif ch == 'f':
            self._lt = 1; self._lp = 1; self._ph = "LIT"
        elif ch == 'n':
            self._lt = 2; self._lp = 1; self._ph = "LIT"
        else:
            self._err(off, f"cannot start value: {ch!r}")

    # --- top-level string ---
    def _do_str(self, ch: str, off: int) -> None:
        self._buf.append(ch)
        if self._check_limit(off): return
        if ch == '"':
            self._ph = "BETWEEN"
            self._emit_q.append(json.loads("".join(self._buf)))
            self._buf = []
        elif ch == '\\':
            self._ph = "STR_ESC"
        elif ch <= '\x1f':
            self._err(off, "unescaped control char in string")

    def _do_str_esc(self, ch: str, off: int) -> None:
        self._buf.append(ch)
        if self._check_limit(off): return
        if ch in _ESC:
            self._ph = "STR"
        elif ch == 'u':
            self._hex_n = 1; self._ph = "STR_HEX"
        else:
            self._err(off, f"invalid escape \\{ch}")

    def _do_str_hex(self, ch: str, off: int) -> None:
        self._buf.append(ch)
        if self._check_limit(off): return
        if ch in _HEX:
            self._hex_n += 1
            if self._hex_n > 4:
                self._ph = "STR"
        else:
            self._err(off, "invalid \\u escape")

    # --- top-level number ---
    def _do_num(self, ch: str, off: int, out: list[Any]) -> None:
        self._buf.append(ch)
        if self._check_limit(off): return
        ns = self._ns
        if ns == _NS_AFTER_MINUS:
            if '0' <= ch <= '9':
                self._ns = _NS_ZERO if ch == '0' else _NS_INT
            else:
                self._err(off, "expected digit after '-'")
        elif ns == _NS_INT:
            if '0' <= ch <= '9':
                pass
            elif ch == '.':
                self._ns = _NS_FRAC
            elif ch in 'eE':
                self._ns = _NS_EXP_START
            else:
                self._buf.pop()
                self._top_term(ch, off, out, "NUMTERM")
        elif ns == _NS_ZERO:
            if '0' <= ch <= '9':
                self._err(off, "leading zero")
            elif ch == '.':
                self._ns = _NS_FRAC
            elif ch in 'eE':
                self._ns = _NS_EXP_START
            else:
                self._buf.pop()
                self._top_term(ch, off, out, "NUMTERM")
        elif ns == _NS_FRAC:
            if '0' <= ch <= '9':
                pass
            elif ch in 'eE':
                self._ns = _NS_EXP_START
            else:
                self._err(off, "expected digit in fraction")
        elif ns == _NS_EXP_START:
            if ch in '+-':
                self._ns = _NS_EXP_SIGN
            elif '0' <= ch <= '9':
                self._ns = _NS_EXP_DIGITS
            else:
                self._err(off, "expected digit/sign in exponent")
        elif ns == _NS_EXP_SIGN:
            if '0' <= ch <= '9':
                self._ns = _NS_EXP_DIGITS
            else:
                self._err(off, "expected digit in exponent")
        elif ns == _NS_EXP_DIGITS:
            if '0' <= ch <= '9':
                pass
            else:
                self._err(off, f"invalid in number: {ch!r}")

    # --- top-level literal ---
    def _do_lit(self, ch: str, off: int) -> None:
        self._buf.append(ch)
        if self._check_limit(off): return
        w = _LIT_WORDS[self._lt]
        if ch == w[self._lp]:
            self._lp += 1
            if self._lp == len(w):
                self._ph = "LITERM"
        else:
            self._err(off, "invalid literal")

    # --- terminator states ---
    def _top_term(self, ch: str, off: int, out: list[Any], term_ph: str) -> None:
        if ch in _WS:
            out.append(json.loads("".join(self._buf)))
            self._buf = []
            self._ph = "BETWEEN"
        elif ch in '{[''"':
            out.append(json.loads("".join(self._buf)))
            self._buf = []
            self._ph = "BETWEEN"
            self._deferred = ch
        else:
            self._err(off, f"invalid after value: {ch!r}")

    def _do_numterm(self, ch: str, off: int, out: list[Any]) -> None:
        self._top_term(ch, off, out, "NUMTERM")

    def _do_literm(self, ch: str, off: int, out: list[Any]) -> None:
        self._top_term(ch, off, out, "LITERM")

    # --- container ---
    def _do_cont(self, ch: str, off: int, out: list[Any]) -> None:
        self._buf.append(ch)
        if self._check_limit(off): return
        if self._cv_str:
            self._cont_str(ch, off)
        elif self._cv_num:
            self._cont_num(ch, off, out)
        elif self._cv_lit:
            self._cont_lit(ch, off)
        else:
            is_obj, fs = self._stk[-1]
            if is_obj:
                self._cont_obj(ch, off, fs, out)
            else:
                self._cont_arr(ch, off, fs, out)

    def _cont_str(self, ch: str, off: int) -> None:
        if self._cv_esc:
            self._cv_esc = False
            if ch in _ESC:
                pass
            elif ch == 'u':
                self._cv_hex = 1
            else:
                self._err(off, f"invalid escape \\{ch}")
            return
        if self._cv_hex > 0:
            if ch in _HEX:
                self._cv_hex += 1
                if self._cv_hex > 4:
                    self._cv_hex = 0
            else:
                self._err(off, "invalid \\u escape")
            return
        if ch == '"':
            self._cv_str = False
            self._cont_val_done()
        elif ch == '\\':
            self._cv_esc = True
        elif ch <= '\x1f':
            self._err(off, "unescaped control char in string")

    def _cont_num(self, ch: str, off: int, out: list[Any]) -> None:
        ns = self._ns
        done = False
        if ns == _NS_AFTER_MINUS:
            if '0' <= ch <= '9':
