            return
        if ns in (_NS_INT, _NS_ZERO, _NS_FRAC, _NS_EXP_DIGITS):
            if ns == _NS_ZERO and '0' <= ch <= '9':
                self._err(off, "leading zero"); return
            if '0' <= ch <= '9':
