            else:
                self._err(off, "expected digit in exponent")
            return
        if done:
            self._cv_num = False
            self._cont_val_done()
            self._cont_struct(ch, off, out)

    def _cont_lit(self, ch: str, off: int) -> None:
        w = _LIT_WORDS[self._lt]
        if ch == w[self._lp]:
            self._lp += 1
            if self._lp == len(w):
                self._cv_lit = False
                self._cont_val_done()
        elif ch in ',}]':
            self._err(off, "incomplete literal")
        else:
            self._err(off, "invalid literal")

